export const PUBLIC_REGISTRATION_HTML = "<!doctype html>\n<html lang=\"fr\">\n<head>\n  <meta charset=\"utf-8\" />\n  <meta name=\"viewport\" content=\"width=device-width,initial-scale=1,viewport-fit=cover\" />\n  <meta name=\"theme-color\" content=\"#173f49\" />\n  <meta name=\"sekoly-build\" content=\"2026-10-04-secure-submission-v2\" />\n  <title>Préinscription Sekoly</title>\n  <style>\n    :root{color-scheme:light;--bg:#eef5f5;--card:#fff;--card2:#f8fbfb;--ink:#17242b;--muted:#687780;--line:#d8e4e7;--brand:#173f49;--brand2:#245d68;--accent:#2f7a54;--accentSoft:#eaf6ef;--danger:#b94141;--warning:#9a651f;--shadow:0 18px 55px rgba(21,56,66,.10)}\n    html[data-theme=\"dark\"]{color-scheme:dark;--bg:#0c1519;--card:#132027;--card2:#17262d;--ink:#eef5f6;--muted:#9db0b8;--line:#2a3d45;--brand:#194b57;--brand2:#276a77;--accent:#70c096;--accentSoft:#18372a;--danger:#ef8d8d;--warning:#e7b76f;--shadow:0 18px 55px rgba(0,0,0,.28)}\n    *{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;min-height:100vh;background:linear-gradient(180deg,#e5f0ef 0,var(--bg) 430px);color:var(--ink);font-family:Inter,ui-sans-serif,system-ui,-apple-system,\"Segoe UI\",sans-serif;transition:.2s}html[data-theme=\"dark\"] body{background:linear-gradient(180deg,#091519 0,var(--bg) 430px)}\n    button,input,select,textarea{font:inherit}.shell{max-width:920px;margin:0 auto;padding:16px 14px 70px}.hero{position:relative;overflow:hidden;padding:28px;border-radius:24px;background:linear-gradient(145deg,var(--brand),var(--brand2));color:white;box-shadow:var(--shadow)}.hero:after{content:\"\";position:absolute;width:330px;height:330px;border-radius:50%;background:rgba(255,255,255,.06);right:-130px;top:-180px}.hero-tools{position:absolute;z-index:2;right:18px;top:16px;display:flex;gap:7px}.tool{border:1px solid rgba(255,255,255,.24);background:rgba(255,255,255,.08);color:white;border-radius:999px;padding:7px 10px;font-size:10px;font-weight:800;backdrop-filter:blur(8px)}button.tool{cursor:pointer}.dot{display:inline-block;width:7px;height:7px;border-radius:50%;background:#7ad7a5;margin-right:5px}.dot.offline{background:#efb06a}.brand{font-size:11px;font-weight:900;letter-spacing:.19em;opacity:.82}.hero h1{position:relative;margin:10px 0 5px;font-size:28px;line-height:1.1}.hero p{position:relative;margin:0;color:#d9e6e8}.campaign{position:relative;display:inline-flex;margin-top:16px;border:1px solid rgba(255,255,255,.22);border-radius:999px;padding:7px 10px;font-size:11px}\n    .notice{margin-top:14px;padding:13px 15px;border-left:4px solid var(--accent);border-radius:12px;background:var(--accentSoft);font-size:12px;line-height:1.55}.progress{display:grid;grid-template-columns:repeat(4,1fr);gap:8px;margin:16px 0}.step-chip{border:1px solid var(--line);background:var(--card);border-radius:14px;padding:10px 9px;color:var(--muted);font-size:10px;font-weight:850;text-align:center}.step-chip.active{background:var(--brand);border-color:var(--brand);color:white}.step-chip.done{border-color:rgba(47,122,84,.4);color:var(--accent)}\n    .card{margin-top:14px;padding:20px;border:1px solid var(--line);border-radius:20px;background:var(--card);box-shadow:0 8px 26px rgba(20,49,58,.045)}.card h2{margin:0 0 5px;font-size:16px}.sub{margin:0 0 16px;color:var(--muted);font-size:11px;line-height:1.55}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.span2{grid-column:span 2}.field label{display:block;margin-bottom:5px;color:var(--muted);font-size:10px;font-weight:850;text-transform:uppercase;letter-spacing:.045em}.field input,.field select,.field textarea{width:100%;min-height:46px;border:1px solid var(--line);border-radius:12px;background:var(--card2);color:var(--ink);padding:10px 12px;outline:none;transition:.15s}.field textarea{min-height:84px;resize:vertical}.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--accent);box-shadow:0 0 0 3px rgba(47,122,84,.10)}.divider{height:1px;background:var(--line);margin:17px 0}.section-title{font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.06em;color:var(--muted);margin-bottom:10px}\n    .child{margin-top:12px;padding:16px;border:1px solid var(--line);border-radius:16px;background:var(--card2)}.child-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:13px}.child-head strong{font-size:13px}.doc-box{padding:13px;border:1px dashed var(--line);border-radius:14px;background:var(--card2)}.doc-box label{display:block;font-size:10px;font-weight:850;color:var(--muted);margin-bottom:6px}.doc-box input{width:100%;font-size:11px}.docs-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px}\n    .actions{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-top:16px}.btn{min-height:44px;border:0;border-radius:12px;padding:10px 15px;font-weight:850;cursor:pointer}.btn:disabled{opacity:.55;cursor:not-allowed}.primary{background:var(--brand);color:white}.secondary{background:var(--card2);color:var(--ink);border:1px solid var(--line)}.success{background:var(--accent);color:white}.danger{background:rgba(185,65,65,.1);color:var(--danger)}.add{background:var(--accentSoft);color:var(--accent)}.fine{color:var(--muted);font-size:10px;line-height:1.55}.review{display:grid;gap:8px}.review-row{display:flex;justify-content:space-between;gap:18px;padding:11px 12px;border:1px solid var(--line);border-radius:12px;background:var(--card2);font-size:11px}.review-row span{color:var(--muted)}.consent{display:flex;gap:9px;align-items:flex-start;margin-top:15px;font-size:11px;color:var(--muted)}.consent input{margin-top:2px}.saving{min-height:16px;margin-top:8px;color:var(--muted);font-size:10px}.hidden{display:none!important}.loading{padding:42px;text-align:center;color:var(--muted)}.error-card{margin-top:16px;padding:18px;border-radius:16px;background:rgba(185,65,65,.09);color:var(--danger);font-size:12px}.success-card{text-align:center;padding:30px}.checkmark{width:54px;height:54px;margin:0 auto 12px;border-radius:50%;display:grid;place-items:center;background:var(--accent);color:white;font-size:27px;font-weight:900}.reference{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:22px;font-weight:900;margin:12px 0}.portal-link{display:inline-flex;margin-top:12px;text-decoration:none}\n    .custom-fields-title{grid-column:1/-1;margin:6px 0 0;padding-top:12px;border-top:1px solid var(--line);font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.06em;color:var(--muted)}.field-note{display:block;margin-top:4px;color:var(--muted);font-size:9px;line-height:1.4}\n    .form-sections{display:grid;gap:14px;margin-top:12px}.form-section{min-width:0;margin:0;padding:14px;border:1px solid var(--line);border-radius:16px;background:var(--card2)}.form-section legend{padding:0 7px;font-size:12px;font-weight:900;color:var(--ink)}.form-section-desc{margin:-2px 0 11px;color:var(--muted);font-size:10px;line-height:1.5}\n    .portal-wrap{display:grid;gap:14px}.portal-card{padding:18px;border:1px solid var(--line);border-radius:18px;background:var(--card);box-shadow:0 8px 26px rgba(20,49,58,.045)}.portal-head{display:flex;justify-content:space-between;align-items:flex-start;gap:14px}.portal-title{margin:0;font-size:15px}.portal-code{font-family:ui-monospace,SFMono-Regular,Menlo,monospace;font-size:11px;color:var(--muted);margin-top:4px}.portal-row{display:flex;justify-content:space-between;align-items:center;gap:12px;padding:11px 0;border-bottom:1px solid var(--line)}.portal-row:last-child{border-bottom:0}.portal-row small{display:block;color:var(--muted);margin-top:3px}.pill{display:inline-flex;padding:5px 8px;border-radius:999px;background:var(--card2);font-size:9px;font-weight:850}.checklist{display:grid;gap:7px;margin-top:10px}.check-item{display:flex;align-items:center;gap:8px;flex-wrap:wrap;padding:8px 9px;border:1px solid var(--line);border-radius:10px;background:var(--card2);font-size:10px}.check-item>span{flex:1;min-width:150px}.state-good{color:var(--accent)}.state-warn{color:var(--warning)}.mini-upload{display:inline-flex;align-items:center;padding:6px 8px;border-radius:8px;background:var(--accentSoft);color:var(--accent);font-size:9px;font-weight:850;cursor:pointer}.mini-upload input{display:none}.portal-actions{display:flex;flex-wrap:wrap;gap:8px;margin-top:12px}\n    @media(max-width:700px){.shell{padding:8px 10px 60px}.hero{padding:58px 20px 22px;border-radius:20px}.hero-tools{right:12px;top:12px}.hero h1{font-size:22px}.progress{gap:5px}.step-chip{padding:8px 4px;font-size:8px}.card{padding:16px}.grid,.docs-grid{grid-template-columns:1fr}.span2{grid-column:auto}.actions{position:sticky;bottom:8px;z-index:5;padding:8px;border:1px solid var(--line);border-radius:14px;background:color-mix(in srgb,var(--card) 94%,transparent);backdrop-filter:blur(8px)}.actions .btn{flex:1}.review-row{align-items:flex-start}}\n  </style>\n</head>\n<body>\n  <main class=\"shell\">\n    <section class=\"hero\">\n      <div class=\"hero-tools\">\n        <span class=\"tool\"><span id=\"netDot\" class=\"dot\"></span><span id=\"netLabel\">En ligne</span></span>\n        <button id=\"themeToggle\" class=\"tool\" type=\"button\">Mode sombre</button>\n      </div>\n      <div class=\"brand\">SEKOLY · INSCRIPTION</div>\n      <h1 id=\"schoolName\">Chargement…</h1>\n      <p id=\"schoolMeta\">Préparation du formulaire sécurisé</p>\n      <div id=\"campaignName\" class=\"campaign\">Préinscription</div>\n    </section>\n\n    <div id=\"notice\" class=\"notice hidden\"></div>\n\n    <div id=\"progress\" class=\"progress\">\n      <div class=\"step-chip active\">1 · Famille</div>\n      <div class=\"step-chip\">2 · Enfant(s)</div>\n      <div class=\"step-chip\">3 · Pièces</div>\n      <div class=\"step-chip\">4 · Vérifier</div>\n    </div>\n\n    <div id=\"loading\" class=\"card loading\">Chargement du formulaire…</div>\n    <div id=\"fatal\" class=\"error-card hidden\"></div>\n\n    <form id=\"form\" class=\"hidden\" novalidate>\n      <section class=\"card step\" data-step=\"0\">\n        <h2>Responsable familial</h2>\n        <p class=\"sub\">Renseignez le parent ou responsable qui sera contacté en priorité par l’établissement.</p>\n        <div class=\"grid\">\n          <div class=\"field\"><label>Nom *</label><input name=\"guardianLastName\" autocomplete=\"family-name\" required maxlength=\"120\"></div>\n          <div class=\"field\"><label>Prénoms</label><input name=\"guardianFirstName\" autocomplete=\"given-name\" maxlength=\"120\"></div>\n          <div class=\"field\"><label>Lien avec l’enfant *</label><select name=\"relationship\"><option value=\"FATHER\">Père</option><option value=\"MOTHER\">Mère</option><option value=\"GUARDIAN\">Tuteur / responsable légal</option><option value=\"OTHER\">Autre</option></select></div>\n          <div class=\"field\"><label>Téléphone principal *</label><input name=\"phonePrimary\" autocomplete=\"tel\" inputmode=\"tel\" required maxlength=\"40\"></div>\n          <div class=\"field\"><label>Deuxième téléphone</label><input name=\"phoneSecondary\" inputmode=\"tel\" maxlength=\"40\"></div>\n          <div class=\"field\"><label>Email</label><input name=\"email\" type=\"email\" autocomplete=\"email\" maxlength=\"160\"></div>\n          <div class=\"field\"><label>N° CIN</label><input name=\"cinNumber\" maxlength=\"80\"></div>\n          <div class=\"field\"><label>Date de délivrance CIN</label><input name=\"cinIssuedAt\" type=\"date\"></div>\n          <div class=\"field\"><label>Lieu de délivrance CIN</label><input name=\"cinIssuePlace\" maxlength=\"160\"></div>\n          <div class=\"field\"><label>Profession</label><input name=\"occupation\" maxlength=\"160\"></div>\n          <div class=\"field span2\"><label>Adresse</label><input name=\"address\" autocomplete=\"street-address\" maxlength=\"250\"></div>\n          <div class=\"field\"><label>Ville / Commune</label><input name=\"city\" maxlength=\"120\"></div>\n          <div class=\"field\"><label>Contact préféré</label><select name=\"preferredContact\"><option value=\"PHONE\">Appel</option><option value=\"WHATSAPP\">WhatsApp</option><option value=\"SMS\">SMS</option><option value=\"EMAIL\">Email</option></select></div>\n        </div>\n\n        <div class=\"divider\"></div>\n        <div class=\"section-title\">Deuxième responsable (facultatif)</div>\n        <div class=\"grid\">\n          <div class=\"field\"><label>Lien</label><select name=\"secondaryRelationship\"><option value=\"OTHER\">Autre responsable</option><option value=\"FATHER\">Père</option><option value=\"MOTHER\">Mère</option><option value=\"GUARDIAN\">Tuteur</option></select></div>\n          <div class=\"field\"><label>Nom</label><input name=\"secondaryLastName\" maxlength=\"120\"></div>\n          <div class=\"field\"><label>Prénoms</label><input name=\"secondaryFirstName\" maxlength=\"120\"></div>\n          <div class=\"field\"><label>Téléphone</label><input name=\"secondaryPhonePrimary\" inputmode=\"tel\" maxlength=\"40\"></div>\n          <div class=\"field\"><label>Email</label><input name=\"secondaryEmail\" type=\"email\" maxlength=\"160\"></div>\n          <div class=\"field\"><label>N° CIN</label><input name=\"secondaryCinNumber\" maxlength=\"80\"></div>\n          <div class=\"field\"><label>Date CIN</label><input name=\"secondaryCinIssuedAt\" type=\"date\"></div>\n          <div class=\"field\"><label>Lieu CIN</label><input name=\"secondaryCinIssuePlace\" maxlength=\"160\"></div>\n          <div class=\"field span2\"><label>Profession</label><input name=\"secondaryOccupation\" maxlength=\"160\"></div>\n        </div>\n        <div id=\"customFamilyFields\" class=\"grid\" style=\"margin-top:12px\"></div>\n        <div id=\"familySections\" class=\"form-sections\"></div>\n        <div class=\"actions\"><span></span><button type=\"button\" class=\"btn primary\" data-next>Continuer</button></div>\n      </section>\n\n      <section class=\"card step hidden\" data-step=\"1\">\n        <div style=\"display:flex;align-items:flex-start;justify-content:space-between;gap:12px\">\n          <div><h2>Enfant(s)</h2><p class=\"sub\">Vous pouvez envoyer plusieurs dossiers dans la même demande familiale.</p></div>\n          <button id=\"addChild\" type=\"button\" class=\"btn add\">+ Ajouter</button>\n        </div>\n        <div id=\"children\"></div>\n        <div class=\"actions\"><button type=\"button\" class=\"btn secondary\" data-prev>Retour</button><button type=\"button\" class=\"btn primary\" data-next>Continuer</button></div>\n      </section>\n\n      <section class=\"card step hidden\" data-step=\"2\">\n        <h2>Pièces justificatives</h2>\n        <p class=\"sub\">Vous pouvez les joindre maintenant ou les remettre plus tard à l’établissement. PDF, JPG, PNG ou WEBP, 10 Mo maximum.</p>\n        <div class=\"section-title\">Documents de la famille</div>\n        <div id=\"familyDocs\" class=\"docs-grid\"></div>\n        <div class=\"divider\"></div>\n        <div class=\"section-title\">Documents par enfant</div>\n        <div id=\"childDocs\"></div>\n        <div class=\"actions\"><button type=\"button\" class=\"btn secondary\" data-prev>Retour</button><button type=\"button\" class=\"btn primary\" data-next>Continuer</button></div>\n      </section>\n\n      <section class=\"card step hidden\" data-step=\"3\">\n        <h2>Vérification</h2>\n        <p class=\"sub\">Contrôlez les informations avant l’envoi. La demande ne devient une inscription définitive qu’après validation par l’école.</p>\n        <div id=\"review\" class=\"review\"></div>\n        <label class=\"consent\"><input id=\"consent\" type=\"checkbox\"><span>Je confirme que les informations fournies sont exactes et j’autorise l’établissement à me contacter au sujet de cette demande.</span></label>\n        <div id=\"saving\" class=\"saving\"></div>\n        <div class=\"actions\"><button type=\"button\" class=\"btn secondary\" data-prev>Retour</button><button id=\"submitBtn\" type=\"submit\" class=\"btn success\">Envoyer la demande</button></div>\n      </section>\n    </form>\n\n    <section id=\"portalApp\" class=\"portal-wrap hidden\">\n      <article class=\"portal-card\">\n        <div class=\"portal-head\">\n          <div>\n            <h2 class=\"portal-title\" id=\"portalFamilyName\">Portail famille</h2>\n            <div class=\"portal-code\" id=\"portalFamilyCode\"></div>\n          </div>\n          <span class=\"pill\">Accès sécurisé</span>\n        </div>\n        <p class=\"sub\" id=\"portalSchoolName\"></p>\n        <div class=\"portal-actions\">\n          <button id=\"portalNewRequest\" type=\"button\" class=\"btn primary hidden\">Inscrire ou réinscrire un enfant</button>\n          <button id=\"portalRefresh\" type=\"button\" class=\"btn secondary\">Actualiser</button>\n        </div>\n      </article>\n      <article class=\"portal-card\">\n        <h2 class=\"portal-title\">Mes enfants</h2>\n        <div id=\"portalStudents\" style=\"margin-top:8px\"></div>\n      </article>\n      <article class=\"portal-card\">\n        <h2 class=\"portal-title\">Mes demandes</h2>\n        <p class=\"sub\">Suivez l’avancement et ajoutez les pièces encore manquantes.</p>\n        <div id=\"portalApplications\"></div>\n      </article>\n    </section>\n\n    <section id=\"success\" class=\"card success-card hidden\">\n      <div class=\"checkmark\">✓</div>\n      <h2>Demande transmise</h2>\n      <p class=\"sub\">L’établissement vérifiera le dossier puis contactera la famille avant toute inscription définitive.</p>\n      <div class=\"reference\" id=\"reference\"></div>\n      <div id=\"uploadStatus\" class=\"fine\"></div>\n      <a id=\"portalLink\" class=\"btn primary portal-link\" href=\"#\" target=\"_blank\" rel=\"noopener\">Ouvrir mon portail famille</a>\n    </section>\n  </main>\n\n<script>\n(function(){\n  const qs=new URLSearchParams(location.search);\n  const CODE=qs.get('code')||'';\n  const FAMILY=qs.get('family')||'';\n  const PORTAL=qs.get('portal')||'';\n  const ENDPOINT='https://cmpbrouwcfoauwyeiyfj.supabase.co/functions/v1/sekoly-public-enrollment';\n  const DRAFT_KEY='sekoly-enrollment-draft:'+CODE;\n  const form=document.getElementById('form');\n  const children=document.getElementById('children');\n  let bootstrap=null;\n  let childCounter=0;\n  let currentStep=0;\n\n  const q=(s,r=document)=>r.querySelector(s);\n  const qa=(s,r=document)=>Array.from(r.querySelectorAll(s));\n  const esc=(v)=>String(v??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#039;'}[c]));\n\n  const defaultSections=[\n    {id:'family_primary',scope:'FAMILY',title:'Responsable principal',description:'Identité et coordonnées du parent ou responsable à contacter en priorité.',order:10,visible:true},\n    {id:'family_secondary',scope:'FAMILY',title:'Deuxième responsable',description:'Informations facultatives sur un autre parent ou responsable légal.',order:20,visible:true},\n    {id:'child_identity',scope:'CHILD',title:'Identité de l’élève',description:'Informations essentielles permettant d’identifier l’enfant et le type de demande.',order:10,visible:true},\n    {id:'child_schooling',scope:'CHILD',title:'Scolarité',description:'Classe souhaitée et établissement fréquenté auparavant.',order:20,visible:true},\n    {id:'child_civil',scope:'CHILD',title:'État civil et adresse',description:'Acte de naissance, adresse et localisation de l’enfant.',order:30,visible:true},\n    {id:'child_health',scope:'CHILD',title:'Santé et informations utiles',description:'Informations utiles à l’accueil et au suivi de l’élève.',order:40,visible:true}\n  ];\n  const schoolingKeys=new Set(['desiredClassId','previousSchool']);\n  const civilKeys=new Set(['birthCertificateNumber','birthCertificateDate','birthCertificatePlace','address','neighborhood','city']);\n  const healthKeys=new Set(['bloodType','medicalNotes']);\n  function legacySectionId(field){\n    if(field.scope==='FAMILY')return field.group==='SECONDARY'?'family_secondary':'family_primary';\n    if(schoolingKeys.has(field.key))return 'child_schooling';\n    if(civilKeys.has(field.key))return 'child_civil';\n    if(healthKeys.has(field.key))return 'child_health';\n    return 'child_identity';\n  }\n  function schemaSections(scope){\n    const sections=bootstrap?.campaign?.form_schema?.sections;\n    const source=Array.isArray(sections)&&sections.length?sections:defaultSections;\n    return source.filter(s=>s&&s.scope===scope&&s.visible!==false).sort((a,b)=>(Number(a.order)||100)-(Number(b.order)||100));\n  }\n  function schemaFields(scope){\n    const fields=bootstrap?.campaign?.form_schema?.fields;\n    const visibleSections=new Set(schemaSections(scope).map(s=>s.id));\n    return Array.isArray(fields)\n      ? fields.filter(f=>f&&f.scope===scope&&f.visible!==false&&visibleSections.has(f.sectionId||legacySectionId(f))).sort((a,b)=>(Number(a.order)||100)-(Number(b.order)||100))\n      : [];\n  }\n  function schemaDocuments(scope){\n    const docs=bootstrap?.campaign?.form_schema?.documents;\n    return Array.isArray(docs)\n      ? docs.filter(d=>d&&d.scope===scope&&d.visible!==false).sort((a,b)=>(Number(a.order)||100)-(Number(b.order)||100))\n      : [];\n  }\n  function fieldInputHtml(field,scope){\n    const customAttr=scope==='FAMILY'?'data-custom-family-key':'data-custom-child-key';\n    const name=scope==='FAMILY'?' name=\"customFamily__'+esc(field.key)+'\"':'';\n    const req=field.required?' required':'';\n    const placeholder=field.placeholder?' placeholder=\"'+esc(field.placeholder)+'\"':'';\n    const id='custom-'+scope.toLowerCase()+'-'+String(field.key).replace(/[^a-zA-Z0-9_-]/g,'-');\n    const helpId=field.helpText?id+'-help':'';\n    const described=helpId?' aria-describedby=\"'+esc(helpId)+'\"':'';\n    const common=' id=\"'+esc(id)+'\" '+customAttr+'=\"'+esc(field.key)+'\"'+name+req+placeholder+described;\n    if(field.type==='TEXTAREA')return '<textarea '+common+' maxlength=\"4000\"></textarea>';\n    if(field.type==='DATE')return '<input type=\"date\" '+common+'>';\n    if(field.type==='EMAIL')return '<input type=\"email\" '+common+' maxlength=\"500\">';\n    if(field.type==='PHONE')return '<input type=\"tel\" inputmode=\"tel\" '+common+' maxlength=\"500\">';\n    if(field.type==='NUMBER')return '<input type=\"number\" '+common+'>';\n    if(field.type==='YES_NO')return '<select '+common+'><option value=\"\"></option><option value=\"true\">Oui</option><option value=\"false\">Non</option></select>';\n    if(field.type==='SELECT'){\n      const opts=(Array.isArray(field.options)?field.options:[]).map(v=>'<option value=\"'+esc(v)+'\">'+esc(v)+'</option>').join('');\n      return '<select '+common+'><option value=\"\"></option>'+opts+'</select>';\n    }\n    return '<input type=\"text\" '+common+' maxlength=\"500\">';\n  }\n  function customFieldsHtml(scope){\n    const custom=schemaFields(scope).filter(f=>f.custom);\n    return custom.map(field=>{\n      const id='custom-'+scope.toLowerCase()+'-'+String(field.key).replace(/[^a-zA-Z0-9_-]/g,'-');\n      const status=field.required?' (obligatoire)':' (facultatif)';\n      const helpId=id+'-help';\n      return '<div class=\"field\"><label for=\"'+esc(id)+'\">'+esc(field.label)+status+'</label>'+fieldInputHtml(field,scope)+(field.helpText?'<small id=\"'+esc(helpId)+'\" class=\"field-note\">'+esc(field.helpText)+'</small>':'')+'</div>';\n    }).join('');\n  }\n  function customAnswerValue(el){\n    if(!el)return '';\n    if(el.tagName==='SELECT'&&el.dataset&&el.dataset.customFamilyKey&&el.options)return el.value;\n    if(el.type==='number')return el.value===''?'':Number(el.value);\n    if(el.type==='checkbox')return Boolean(el.checked);\n    if(el.value==='true')return true;\n    if(el.value==='false')return false;\n    return String(el.value||'').trim();\n  }\n  function readCustomAnswers(scope,root=document){\n    const attr=scope==='FAMILY'?'data-custom-family-key':'data-custom-child-key';\n    const out={};\n    qa('['+attr+']',root).forEach(el=>{\n      const key=el.getAttribute(attr);\n      if(!key)return;\n      const value=customAnswerValue(el);\n      if(value!==''&&value!=null)out[key]=value;\n    });\n    return out;\n  }\n  function applyFixedField(field,el){\n    if(!el)return;\n    const box=el.closest('.field');\n    if(box)box.classList.toggle('hidden',field.visible===false);\n    const required=field.visible!==false&&Boolean(field.required);\n    el.required=required;\n    el.setAttribute('aria-required',required?'true':'false');\n    const safeKey=String(field.key||el.name||'field').replace(/[^a-zA-Z0-9_-]/g,'-');\n    const id=el.id||'field-'+String(field.scope||'form').toLowerCase()+'-'+safeKey;\n    el.id=id;\n    const label=box&&q('label',box);\n    if(label){\n      label.htmlFor=id;\n      if(field.label)label.textContent=field.label+(required?' (obligatoire)':' (facultatif)');\n    }\n    if(box){\n      const existing=q('.field-note[data-schema-help=\"true\"]',box);\n      if(field.helpText&&field.visible!==false){\n        const helpId=id+'-help';\n        const note=existing||document.createElement('small');\n        note.className='field-note';\n        note.dataset.schemaHelp='true';\n        note.id=helpId;\n        note.textContent=field.helpText;\n        if(!existing)box.appendChild(note);\n        el.setAttribute('aria-describedby',helpId);\n      }else{\n        existing?.remove();\n        if(el.getAttribute('aria-describedby')===id+'-help')el.removeAttribute('aria-describedby');\n      }\n    }\n  }\n  function renderScopeSections(scope,root){\n    const host=scope==='FAMILY'?q('#familySections'):q('[data-child-sections]',root);\n    if(!host)return;\n    host.innerHTML='';\n    const fields=schemaFields(scope);\n    schemaSections(scope).forEach(section=>{\n      const sectionFields=fields.filter(field=>(field.sectionId||legacySectionId(field))===section.id);\n      const nodes=[];\n      sectionFields.forEach(field=>{\n        const el=field.custom\n          ? q('['+(scope==='FAMILY'?'data-custom-family-key':'data-custom-child-key')+'=\"'+field.key+'\"]',root)\n          : scope==='FAMILY'?form.elements[field.key]:q('[data-field=\"'+field.key+'\"]',root);\n        const box=el?.closest('.field');\n        if(box)nodes.push(box);\n      });\n      if(!nodes.length)return;\n      const fieldset=document.createElement('fieldset');\n      fieldset.className='form-section';\n      const legend=document.createElement('legend');\n      legend.textContent=section.title||'Informations';\n      fieldset.appendChild(legend);\n      if(section.description){\n        const desc=document.createElement('div');\n        desc.className='form-section-desc';\n        desc.textContent=section.description;\n        fieldset.appendChild(desc);\n      }\n      const grid=document.createElement('div');\n      grid.className='grid';\n      nodes.forEach(node=>grid.appendChild(node));\n      fieldset.appendChild(grid);\n      host.appendChild(fieldset);\n    });\n  }\n\n  function applyFamilySchema(){\n    const activeSections=new Set(schemaSections('FAMILY').map(section=>section.id));\n    const fixed=(bootstrap?.campaign?.form_schema?.fields||[]).filter(f=>f&&f.scope==='FAMILY'&&!f.custom);\n    fixed.forEach(field=>applyFixedField({...field,visible:field.visible!==false&&activeSections.has(field.sectionId||legacySectionId(field))},form.elements[field.key]));\n    q('#customFamilyFields').innerHTML=customFieldsHtml('FAMILY');\n    const familyStep=q('[data-step=\"0\"]');\n    q('.divider',familyStep)?.classList.add('hidden');\n    q('.section-title',familyStep)?.classList.add('hidden');\n    renderScopeSections('FAMILY',form);\n    applyFamilyDocumentSchema();\n  }\n  function applyChildSchema(block){\n    const activeSections=new Set(schemaSections('CHILD').map(section=>section.id));\n    const fixed=(bootstrap?.campaign?.form_schema?.fields||[]).filter(f=>f&&f.scope==='CHILD'&&!f.custom);\n    fixed.forEach(field=>applyFixedField({...field,visible:field.visible!==false&&activeSections.has(field.sectionId||legacySectionId(field))},q('[data-field=\"'+field.key+'\"]',block)));\n    const custom=q('[data-custom-child-fields]',block);\n    if(custom)custom.innerHTML=customFieldsHtml('CHILD');\n    renderScopeSections('CHILD',block);\n    const type=q('[data-field=\"type\"]',block);\n    if(type){\n      type.addEventListener('change',()=>refreshChildConditional(block));\n      refreshChildConditional(block);\n    }\n  }\n  function refreshChildConditional(block){\n    const type=q('[data-field=\"type\"]',block)?.value||'NEW';\n    const matricule=q('[data-field=\"existingMatricule\"]',block);\n    if(!matricule)return;\n    const field=(bootstrap?.campaign?.form_schema?.fields||[]).find(f=>f.scope==='CHILD'&&f.key==='existingMatricule');\n    const show=field?.visible!==false&&type==='RE_REGISTRATION';\n    const box=matricule.closest('.field');\n    if(box)box.classList.toggle('hidden',!show);\n    matricule.required=show;\n  }\n  function renderFamilyDocs(){\n    q('#familyDocs').innerHTML=schemaDocuments('FAMILY').map(doc=>\n      '<div class=\"doc-box\"><label>'+esc(doc.label)+(doc.required?' (obligatoire)':' (facultatif)')+'</label>'+\n      '<input type=\"file\" data-family-doc-code=\"'+esc(doc.code)+'\" accept=\".pdf,image/jpeg,image/png,image/webp\">'+\n      (doc.helpText?'<small class=\"field-note\">'+esc(doc.helpText)+'</small>':'')+\n      '</div>'\n    ).join('');\n  }\n  function applyFamilyDocumentSchema(){\n    renderFamilyDocs();\n  }\n  function validateSchemaFields(scope,root){\n    for(const field of schemaFields(scope)){\n      if(scope==='CHILD'&&field.key==='existingMatricule'&&q('[data-field=\"type\"]',root)?.value!=='RE_REGISTRATION')continue;\n      const el=field.custom\n        ? q('['+(scope==='FAMILY'?'data-custom-family-key':'data-custom-child-key')+'=\"'+field.key+'\"]',root)\n        : scope==='FAMILY'?form.elements[field.key]:q('[data-field=\"'+field.key+'\"]',root);\n      if(!el)continue;\n      const value=customAnswerValue(el);\n      if(field.required&&(value===''||value==null)){\n        el.focus();\n        alert('Veuillez renseigner : '+field.label);\n        return false;\n      }\n      if(value!==''&&value!=null&&el.checkValidity&&!el.checkValidity()){\n        el.reportValidity?.();\n        return false;\n      }\n    }\n    return true;\n  }\n\n  function applyTheme(theme){\n    document.documentElement.dataset.theme=theme;\n    q('#themeToggle').textContent=theme==='dark'?'Mode clair':'Mode sombre';\n    try{localStorage.setItem('sekoly-family-theme',theme)}catch{}\n  }\n  let pref='light';\n  try{pref=localStorage.getItem('sekoly-family-theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light')}catch{}\n  applyTheme(pref);\n  q('#themeToggle').addEventListener('click',()=>applyTheme(document.documentElement.dataset.theme==='dark'?'light':'dark'));\n\n  function network(){\n    const online=navigator.onLine;\n    q('#netDot').classList.toggle('offline',!online);\n    q('#netLabel').textContent=online?'En ligne':'Hors connexion';\n  }\n  addEventListener('online',network);addEventListener('offline',network);network();\n\n  function classOptions(){\n    return '<option value=\"\">À déterminer avec l’école</option>'+(bootstrap?.classes||[]).map(c=>'<option value=\"'+esc(c.id)+'\">'+esc(c.name)+(c.series?' — '+esc(c.series):'')+'</option>').join('');\n  }\n  function typeOptions(){\n    let out='';\n    if(bootstrap?.campaign?.allow_new_admission) out+='<option value=\"NEW\">Nouvelle inscription</option>';\n    if(bootstrap?.campaign?.allow_re_registration) out+='<option value=\"RE_REGISTRATION\">Réinscription</option>';\n    return out;\n  }\n\n  function childTemplate(i,data={}){\n    return '<div class=\"child\" data-child data-index=\"'+i+'\">'+\n      '<div class=\"child-head\"><strong>Enfant '+(qa('[data-child]').length+1)+'</strong><button type=\"button\" class=\"btn danger\" data-remove>Retirer</button></div>'+\n      '<div class=\"grid\" data-child-standard-fields>'+\n      '<div class=\"field\"><label>Type *</label><select data-field=\"type\">'+typeOptions()+'</select></div>'+\n      '<div class=\"field\"><label>Matricule actuel (réinscription)</label><input data-field=\"existingMatricule\" maxlength=\"80\"></div>'+\n      '<div class=\"field\"><label>Nom *</label><input data-field=\"lastName\" required maxlength=\"120\"></div>'+\n      '<div class=\"field\"><label>Prénoms *</label><input data-field=\"firstName\" required maxlength=\"160\"></div>'+\n      '<div class=\"field\"><label>Sexe</label><select data-field=\"gender\"><option value=\"M\">Masculin</option><option value=\"F\">Féminin</option></select></div>'+\n      '<div class=\"field\"><label>Date de naissance</label><input data-field=\"birthDate\" type=\"date\"></div>'+\n      '<div class=\"field\"><label>Lieu de naissance</label><input data-field=\"birthPlace\" maxlength=\"180\"></div>'+\n      '<div class=\"field\"><label>Nationalité</label><input data-field=\"nationality\" value=\"Malgache\" maxlength=\"80\"></div>'+\n      '<div class=\"field\"><label>Classe souhaitée</label><select data-field=\"desiredClassId\">'+classOptions()+'</select></div>'+\n      '<div class=\"field\"><label>Ancien établissement</label><input data-field=\"previousSchool\" maxlength=\"180\"></div>'+\n      '<div class=\"field\"><label>N° acte de naissance</label><input data-field=\"birthCertificateNumber\" maxlength=\"100\"></div>'+\n      '<div class=\"field\"><label>Date acte</label><input data-field=\"birthCertificateDate\" type=\"date\"></div>'+\n      '<div class=\"field\"><label>Lieu acte</label><input data-field=\"birthCertificatePlace\" maxlength=\"180\"></div>'+\n      '<div class=\"field\"><label>Groupe sanguin</label><input data-field=\"bloodType\" maxlength=\"20\"></div>'+\n      '<div class=\"field span2\"><label>Adresse de l’enfant si différente</label><input data-field=\"address\" maxlength=\"250\"></div>'+\n      '<div class=\"field\"><label>Fokontany / quartier</label><input data-field=\"neighborhood\" maxlength=\"120\"></div>'+\n      '<div class=\"field\"><label>Ville / Commune</label><input data-field=\"city\" maxlength=\"120\"></div>'+\n      '<div class=\"field span2\"><label>Informations utiles / médicales</label><textarea data-field=\"medicalNotes\" maxlength=\"1000\"></textarea></div>'+\n      '</div><div class=\"grid\" data-custom-child-fields style=\"margin-top:12px\"></div><div class=\"form-sections\" data-child-sections></div></div>';\n  }\n\n  function addChild(data={}){\n    if(qa('[data-child]').length>=10)return;\n    const id=childCounter++;\n    children.insertAdjacentHTML('beforeend',childTemplate(id,data));\n    const block=children.lastElementChild;\n    applyChildSchema(block);\n    Object.entries(data||{}).forEach(([k,v])=>{const el=q('[data-field=\"'+k+'\"]',block);if(el&&v!=null&&k!=='customAnswers')el.value=v});\n    Object.entries(data?.customAnswers||{}).forEach(([k,v])=>{const el=q('[data-custom-child-key=\"'+k+'\"]',block);if(el&&v!=null)el.value=String(v)});\n    refreshChildConditional(block);\n    renumber();renderChildDocs();saveDraft();\n  }\n  function renumber(){qa('[data-child]').forEach((b,i)=>q('.child-head strong',b).textContent='Enfant '+(i+1))}\n  children.addEventListener('click',e=>{const b=e.target.closest('[data-remove]');if(!b)return;if(qa('[data-child]').length===1)return;b.closest('[data-child]').remove();renumber();renderChildDocs();saveDraft()});\n  q('#addChild').addEventListener('click',()=>addChild());\n\n  function readChildren(){\n    return qa('[data-child]').map(block=>{\n      const get=n=>q('[data-field=\"'+n+'\"]',block)?.value?.trim()||'';\n      return {\n        type:get('type'),existingMatricule:get('existingMatricule'),lastName:get('lastName'),firstName:get('firstName'),\n        gender:get('gender'),birthDate:get('birthDate'),birthPlace:get('birthPlace'),nationality:get('nationality'),\n        desiredClassId:get('desiredClassId'),previousSchool:get('previousSchool'),birthCertificateNumber:get('birthCertificateNumber'),\n        birthCertificateDate:get('birthCertificateDate'),birthCertificatePlace:get('birthCertificatePlace'),bloodType:get('bloodType'),\n        address:get('address'),neighborhood:get('neighborhood'),city:get('city'),medicalNotes:get('medicalNotes'),\n        customAnswers:readCustomAnswers('CHILD',block)\n      };\n    });\n  }\n\n  function renderChildDocs(){\n    const docs=schemaDocuments('CHILD');\n    q('#childDocs').innerHTML=readChildren().map((child,i)=>{\n      const boxes=docs.map(doc=>\n        '<div class=\"doc-box\"><label>'+esc(doc.label)+(doc.required?' (obligatoire)':' (facultatif)')+'</label>'+\n        '<input type=\"file\" data-child-index=\"'+i+'\" data-doc-code=\"'+esc(doc.code)+'\" accept=\".pdf,image/jpeg,image/png,image/webp\">'+\n        (doc.helpText?'<small class=\"field-note\">'+esc(doc.helpText)+'</small>':'')+\n        '</div>'\n      ).join('');\n      return '<div class=\"child\" style=\"margin-bottom:10px\"><strong>'+esc(child.lastName||'Enfant '+(i+1))+' '+esc(child.firstName||'')+'</strong><div class=\"docs-grid\" style=\"margin-top:10px\">'+boxes+'</div></div>';\n    }).join('');\n  }\n\n  function showStep(n){\n    currentStep=Math.max(0,Math.min(3,n));\n    qa('.step').forEach((s,i)=>s.classList.toggle('hidden',i!==currentStep));\n    qa('.step-chip').forEach((s,i)=>{s.classList.toggle('active',i===currentStep);s.classList.toggle('done',i<currentStep)});\n    if(currentStep===2)renderChildDocs();\n    if(currentStep===3)renderReview();\n    scrollTo({top:Math.max(0,q('#progress').offsetTop-8),behavior:'smooth'});\n  }\n  function validateStep(){\n    if(currentStep===0){\n      if(!validateSchemaFields('FAMILY',form))return false;\n    }\n    if(currentStep===1){\n      const blocks=qa('[data-child]');\n      if(!blocks.length){alert('Ajoutez au moins un enfant.');return false}\n      for(const block of blocks){\n        if(!validateSchemaFields('CHILD',block))return false;\n        const type=q('[data-field=\"type\"]',block)?.value||'NEW';\n        if(type==='RE_REGISTRATION'&&!String(q('[data-field=\"existingMatricule\"]',block)?.value||'').trim()){\n          alert('Le matricule est obligatoire pour une réinscription.');\n          return false;\n        }\n      }\n    }\n    return true;\n  }\n  qa('[data-next]').forEach(b=>b.addEventListener('click',()=>{if(validateStep())showStep(currentStep+1)}));\n  qa('[data-prev]').forEach(b=>b.addEventListener('click',()=>showStep(currentStep-1)));\n\n  function renderReview(){\n    const fd=new FormData(form), list=readChildren();\n    q('#review').innerHTML=\n      '<div class=\"review-row\"><span>Responsable</span><strong>'+esc(String(fd.get('guardianLastName')||'')+' '+String(fd.get('guardianFirstName')||''))+'</strong></div>'+\n      '<div class=\"review-row\"><span>Téléphone</span><strong>'+esc(String(fd.get('phonePrimary')||''))+'</strong></div>'+\n      '<div class=\"review-row\"><span>Nombre d’enfants</span><strong>'+list.length+'</strong></div>'+\n      list.map(c=>'<div class=\"review-row\"><span>'+(c.type==='RE_REGISTRATION'?'Réinscription':'Nouvelle inscription')+'</span><strong>'+esc(c.lastName+' '+c.firstName)+'</strong></div>').join('');\n  }\n\n  function draftPayload(){\n    const obj={fields:{},children:readChildren()};\n    Array.from(form.elements).forEach(el=>{if(el.name&&el.type!=='file'&&el.type!=='checkbox')obj.fields[el.name]=el.value});\n    return obj;\n  }\n  function saveDraft(){try{localStorage.setItem(DRAFT_KEY,JSON.stringify(draftPayload()))}catch{}}\n  let timer=0;form.addEventListener('input',()=>{clearTimeout(timer);timer=setTimeout(saveDraft,250)});\n  function restoreDraft(){\n    try{\n      const raw=localStorage.getItem(DRAFT_KEY);if(!raw)return false;\n      const d=JSON.parse(raw);\n      Object.entries(d.fields||{}).forEach(([k,v])=>{if(form.elements[k])form.elements[k].value=v});\n      (d.children||[]).forEach(addChild);\n      return true;\n    }catch{return false}\n  }\n\n  function applyFamilyPrefill(fam){\n    if(!fam)return;\n    const g=fam.guardian||{};\n    const s=fam.secondaryGuardian||{};\n    const map={\n      guardianLastName:g.lastName,guardianFirstName:g.firstName,relationship:g.relationship,phonePrimary:g.phonePrimary,\n      phoneSecondary:g.phoneSecondary,email:g.email,cinNumber:g.cinNumber,cinIssuedAt:g.cinIssuedAt,cinIssuePlace:g.cinIssuePlace,\n      occupation:g.occupation,address:g.address,city:g.city,secondaryRelationship:s.relationship,secondaryLastName:s.lastName,\n      secondaryFirstName:s.firstName,secondaryPhonePrimary:s.phonePrimary,secondaryEmail:s.email,secondaryCinNumber:s.cinNumber,\n      secondaryCinIssuedAt:s.cinIssuedAt,secondaryCinIssuePlace:s.cinIssuePlace,secondaryOccupation:s.occupation\n    };\n    Object.entries(map).forEach(([k,v])=>{if(form.elements[k]&&v)form.elements[k].value=v});\n  }\n\n  async function uploadOne(file,applicationId,documentCode,access){\n    const fd=new FormData();\n    fd.append('file',file);\n    fd.append('applicationId',applicationId||'');\n    fd.append('documentCode',documentCode||'');\n    const capability=access.familyToken?'family='+encodeURIComponent(access.familyToken):'submission='+encodeURIComponent(access.submissionToken);\n    const res=await fetch(ENDPOINT+'?action=upload&'+capability,{method:'POST',body:fd});\n    const out=await res.json();if(!res.ok)throw new Error(out.error||'Envoi du document impossible.');return out;\n  }\n  async function uploadDocuments(result){\n    const jobs=[];\n    qa('[data-family-doc-code]').forEach(input=>{\n      const file=input.files&&input.files[0];if(!file)return;\n      const code=input.dataset.familyDocCode||'';\n      if(code==='CIN_SECONDARY'&&!String(form.elements.secondaryLastName.value||'').trim())return;\n      jobs.push(uploadOne(file,'',code,result));\n    });\n    qa('[data-doc-code]').forEach(input=>{\n      const file=input.files&&input.files[0];if(!file)return;\n      const app=result.applications&&result.applications[Number(input.dataset.childIndex)];\n      if(app)jobs.push(uploadOne(file,app.id,input.dataset.docCode||'',result));\n    });\n    const settled=await Promise.allSettled(jobs);\n    return {uploaded:settled.filter(x=>x.status==='fulfilled').length,failed:settled.filter(x=>x.status==='rejected').length};\n  }\n\n  form.addEventListener('submit',async e=>{\n    e.preventDefault();\n    if(!q('#consent').checked){alert('Veuillez confirmer l’exactitude des informations.');return}\n    if(!navigator.onLine){alert('Vous êtes hors connexion. Le brouillon est conservé sur ce téléphone. Envoyez le dossier dès que la connexion revient.');return}\n    const button=q('#submitBtn'), saving=q('#saving'), fd=new FormData(form), list=readChildren();\n    button.disabled=true;button.textContent='Envoi en cours…';saving.textContent='Création sécurisée du dossier familial…';\n    try{\n      const res=await fetch(ENDPOINT+'?code='+encodeURIComponent(CODE),{\n        method:'POST',headers:{'Content-Type':'application/json'},\n        body:JSON.stringify({\n          code:CODE,familyToken:FAMILY,clientRequestId:crypto.randomUUID(),\n          customAnswers:readCustomAnswers('FAMILY',form),\n          guardian:{\n            lastName:String(fd.get('guardianLastName')||''),firstName:String(fd.get('guardianFirstName')||''),relationship:String(fd.get('relationship')||'GUARDIAN'),\n            phonePrimary:String(fd.get('phonePrimary')||''),phoneSecondary:String(fd.get('phoneSecondary')||''),email:String(fd.get('email')||''),\n            cinNumber:String(fd.get('cinNumber')||''),cinIssuedAt:String(fd.get('cinIssuedAt')||''),cinIssuePlace:String(fd.get('cinIssuePlace')||''),\n            occupation:String(fd.get('occupation')||''),address:String(fd.get('address')||''),city:String(fd.get('city')||''),preferredContact:String(fd.get('preferredContact')||'PHONE'),\n            secondary:{\n              relationship:String(fd.get('secondaryRelationship')||'OTHER'),lastName:String(fd.get('secondaryLastName')||''),firstName:String(fd.get('secondaryFirstName')||''),\n              phonePrimary:String(fd.get('secondaryPhonePrimary')||''),email:String(fd.get('secondaryEmail')||''),cinNumber:String(fd.get('secondaryCinNumber')||''),\n              cinIssuedAt:String(fd.get('secondaryCinIssuedAt')||''),cinIssuePlace:String(fd.get('secondaryCinIssuePlace')||''),occupation:String(fd.get('secondaryOccupation')||'')\n            }\n          },children:list\n        })\n      });\n      const result=await res.json();if(!res.ok)throw new Error(result.error||'Envoi impossible.');\n      saving.textContent='Dossier créé. Envoi des pièces justificatives…';\n      const up=await uploadDocuments(result);\n      try{localStorage.removeItem(DRAFT_KEY)}catch{}\n      form.classList.add('hidden');q('#progress').classList.add('hidden');q('#reference').textContent=result.referenceCode;\n      q('#uploadStatus').textContent=up.uploaded?up.uploaded+' document(s) transmis'+(up.failed?' · '+up.failed+' échec(s)':''):'Contactez l’établissement pour les pièces manquantes.';\n      q('#portalLink').classList.toggle('hidden',!result.portalUrl);if(result.portalUrl)q('#portalLink').href=result.portalUrl;q('#success').classList.remove('hidden');scrollTo({top:0,behavior:'smooth'});\n    }catch(err){alert(err?.message||'Envoi impossible.');button.disabled=false;button.textContent='Envoyer la demande';saving.textContent=''}\n  });\n\n  const portalStatusLabels={\n    SUBMITTED:'Demande reçue',TO_CONTACT:'À contacter',CONTACTED:'Famille contactée',\n    APPOINTMENT_SCHEDULED:'Rendez-vous prévu',INCOMPLETE:'Dossier incomplet',\n    COMPLETE:'Dossier complet',ACCEPTED:'Accepté',PAYMENT_PENDING:'Paiement à effectuer',\n    APPROVED:'Inscription confirmée',REJECTED:'Non retenu',WITHDRAWN:'Retiré'\n  };\n  async function bootPortal(){\n    q('#progress').classList.add('hidden');\n    form.classList.add('hidden');\n    q('#success').classList.add('hidden');\n    q('#loading').classList.remove('hidden');\n    q('#loading').textContent='Chargement du portail famille…';\n    try{\n      const res=await fetch(ENDPOINT+'?action=portal-bootstrap&portal='+encodeURIComponent(PORTAL),{headers:{'Accept':'application/json'}});\n      const data=await res.json();if(!res.ok)throw new Error(data.error||'Portail indisponible.');\n      q('#schoolName').textContent=data.family.displayName||'Votre famille';\n      q('#schoolMeta').textContent=data.school.name;\n      q('#campaignName').textContent='Portail famille';\n      q('#portalFamilyName').textContent=data.family.displayName||'Votre famille';\n      q('#portalFamilyCode').textContent='Référence famille · '+(data.family.code||'—');\n      q('#portalSchoolName').textContent=data.school.name;\n      q('#portalStudents').innerHTML=(data.students||[]).length\n        ? data.students.map(s=>'<div class=\"portal-row\"><div><strong>'+esc((s.last_name||'')+' '+(s.first_name||''))+'</strong><small>'+esc(s.matricule||'')+'</small></div><span class=\"pill\">'+esc(s.status||'')+'</span></div>').join('')\n        : '<div class=\"fine\">Aucun enfant déjà inscrit n’est encore lié à cette famille.</div>';\n      const checklist=data.checklist||[];\n      q('#portalApplications').innerHTML=(data.applications||[]).length\n        ? data.applications.map(app=>{\n            const items=checklist.filter(i=>i.application_id===app.id);\n            const checks=items.length?'<div class=\"checklist\">'+items.map(item=>{\n              const state=item.status==='VERIFIED'?'Vérifié':item.status==='PROVIDED'?'Reçu':item.status==='NOT_REQUIRED'?'Non requis':'Manquant';\n              const good=['VERIFIED','PROVIDED','NOT_REQUIRED'].includes(item.status);\n              const upload=item.status==='MISSING'\n                ? '<label class=\"mini-upload\">Ajouter<input type=\"file\" data-portal-upload=\"'+esc(item.scope==='FAMILY'?'':app.id)+'\" data-portal-code=\"'+esc(item.code)+'\" accept=\".pdf,image/jpeg,image/png,image/webp\"></label>'\n                :'';\n              return '<div class=\"check-item\"><span>'+esc(item.label)+'</span><b class=\"'+(good?'state-good':'state-warn')+'\">'+esc(state)+'</b>'+upload+'</div>';\n            }).join('')+'</div>':'';\n            return '<div class=\"child\"><div class=\"portal-row\"><div><strong>'+esc((app.child_last_name||'')+' '+(app.child_first_name||''))+'</strong><small>'+(app.application_type==='RE_REGISTRATION'?'Réinscription':'Nouvelle inscription')+'</small></div><span class=\"pill\">'+esc(portalStatusLabels[app.status]||app.status)+'</span></div>'+checks+'</div>';\n          }).join('')\n        : '<div class=\"fine\">Aucune demande récente.</div>';\n      q('#loading').classList.add('hidden');\n      q('#portalApp').classList.remove('hidden');\n      if(data.campaign?.publicCode){\n        const b=q('#portalNewRequest');b.classList.remove('hidden');\n        b.onclick=()=>{location.href='./?code='+encodeURIComponent(data.campaign.publicCode)+'&family='+encodeURIComponent(PORTAL)};\n      }\n      qa('[data-portal-upload]').forEach(input=>input.addEventListener('change',async()=>{\n        const file=input.files&&input.files[0];if(!file)return;\n        input.disabled=true;\n        try{\n          await uploadOne(file,input.dataset.portalUpload,input.dataset.portalCode,{familyToken:PORTAL});\n          await bootPortal();\n        }catch(err){alert(err?.message||'Envoi impossible.');input.disabled=false}\n      }));\n    }catch(err){\n      q('#loading').classList.add('hidden');\n      q('#fatal').textContent=err?.message||'Portail famille indisponible.';\n      q('#fatal').classList.remove('hidden');\n    }\n  }\n  q('#portalRefresh').addEventListener('click',()=>{if(PORTAL)bootPortal()});\n\n  async function boot(){\n    if(!CODE){q('#loading').classList.add('hidden');q('#fatal').textContent='Lien d’inscription incomplet. Demandez un nouveau QR code à l’établissement.';q('#fatal').classList.remove('hidden');return}\n    try{\n      const url=ENDPOINT+'?action=bootstrap&code='+encodeURIComponent(CODE)+(FAMILY?'&family='+encodeURIComponent(FAMILY):'');\n      const res=await fetch(url,{headers:{'Accept':'application/json'}});\n      const data=await res.json();if(!res.ok)throw new Error(data.error||'Formulaire indisponible.');\n      bootstrap=data;\n      q('#schoolName').textContent=data.school.name;q('#schoolMeta').textContent='Préinscription en ligne · '+data.year.label;q('#campaignName').textContent=data.campaign.name;\n      if(data.campaign.instructions){q('#notice').textContent=data.campaign.instructions;q('#notice').classList.remove('hidden')}\n      applyFamilySchema();\n      q('#loading').classList.add('hidden');form.classList.remove('hidden');\n      const restored=restoreDraft();if(!restored){applyFamilyPrefill(data.family);addChild()}else if(!qa('[data-child]').length)addChild();\n    }catch(err){q('#loading').classList.add('hidden');q('#fatal').textContent=err?.message||'Le formulaire est momentanément indisponible.';q('#fatal').classList.remove('hidden')}\n  }\n  if(PORTAL && !CODE){bootPortal()}else{boot()}\n})();\n</script>\n</body>\n</html>\n";
